arguments.command:
# Let me write a proper C# program to parse the binlog
mkdir -p /tmp/binlog_parser && cd /tmp/binlog_parser
dotnet new console --force -q
dotnet add package MSBuild.StructuredLogger -q 2>&1 | tail -5

cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine($"Total warnings: {warnings.Count}");
Console.WriteLine();

Console.WriteLine("=== ALL ERRORS ===");
foreach (var error in errors)
{
    var project = error.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {error.Code}: {error.Text}");
    if (!string.IsNullOrEmpty(error.File))
        Console.WriteLine($"  File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine();
}

// Also check for project build failures
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (!p.Succeeded)
        Console.WriteLine($"FAILED: {p.Name} ({p.ProjectFile})");
}
EOF

