    var items = p.FindChildrenRecursive<Item>();
    foreach (var item in items)
    {
        if (item.Name == "ProjectReference")
            Console.WriteLine($"  -> References: {item.Text}");
    }
    var pkgRefs = p.FindChildrenRecursive<AddItem>();
    foreach (var ai in pkgRefs)
    {
        if (ai.Name == "PackageReference")
        {
            foreach (var child in ai.Children.OfType<Item>())
                Console.WriteLine($"  -> Package: {child.Text}");
        }
    }
}

// Get the source file content from the error
Console.WriteLine("\n=== ERROR DETAILS WITH CONTEXT ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var error in errors)
{
    var project = error.GetNearestParent<Project>();
    Console.WriteLine($"Project: {project?.Name}");
    Console.WriteLine($"  Code: {error.Code}");
    Console.WriteLine($"  Message: {error.Text}");
    Console.WriteLine($"  File: {error.File}:{error.LineNumber}:{error.ColumnNumber}");
    Console.WriteLine();
}

// Check which projects depend on Services
Console.WriteLine("=== DEPENDENCY ANALYSIS ===");
foreach (var p in projects)
{
    var refs = p.FindChildrenRecursive<Item>()
        .Where(i => i.Name == "ProjectReference" && i.Text.Contains("Services"));
    foreach (var r in refs)
        Console.WriteLine($"{p.Name} depends on Services.csproj");
}

